from __future__ import annotations

import logging

from aiogram import F, Router
from aiogram.enums import ContentType
from aiogram.types import Message

from bot.config import Settings

logger = logging.getLogger(__name__)

# Join/leave service messages Telegram posts in the managed supergroup(s) as members are
# approved (join-request) or kicked on expiry — noise generated by the bot's own actions.
# Broadcast channels don't emit these, so the handler is a harmless no-op there.
_SERVICE_CONTENT_TYPES = [ContentType.NEW_CHAT_MEMBERS, ContentType.LEFT_CHAT_MEMBER]


async def delete_service_message(message: Message, settings: Settings) -> None:
    """Delete a join/leave service message in the bot's protected chats (best effort).

    Scoped to ``settings.access.protected_chats`` so unrelated groups and the service log
    channel are never touched. Deletion needs the ``can_delete_messages`` admin right; any
    failure (message too old / already gone / missing rights) is swallowed and logged.
    """
    managed_chat_ids = {chat.chat_id for chat in settings.access.protected_chats}
    if message.chat.id not in managed_chat_ids:
        return

    try:
        await message.delete()
    except Exception:
        logger.debug(
            "could not delete service message",
            extra={"chat_id": message.chat.id, "message_id": message.message_id},
            exc_info=True,
        )


def create_service_cleanup_router() -> Router:
    router = Router(name="service_cleanup")
    router.message(F.content_type.in_(_SERVICE_CONTENT_TYPES))(delete_service_message)
    return router
